  function cancellationStatusLabel(value) { const key = String(value || "").trim().toUpperCase(); const labels = { OPEN: "Cancellation requested", REQUESTED: "Cancellation requested", UNDER_REVIEW: "Cancellation under review", APPROVED: "Cancellation approved", REJECTED: "Cancellation rejected", CANCELLED: "Order cancelled", CANCELED: "Order cancelled", CLOSED: "Cancellation closed" }; return labels[key] || titleCaseStatus(value); }
