  function cancellationOrderNumber(o) { return firstText(o?.orderNumber, o?.name, o?.orderName); }
  function cancellationActionState(o) { const status = firstText(o?.latestCancellationStatus, o?.requests?.cancellation?.status); if (status) return { available: false, status, title: cancellationStatusLabel(status), copy: "A cancellation request already exists for this order." }; if (o?.canRequestCancellation === true) return { available: true, title: "Cancel order", copy: "Request cancellation before the order is shipped." }; return { available: false, title: "Cancellation unavailable", copy: cancellationLockReason(o) }; }
