  function renderCancellationUpdate(o) { const rows = []; const status = firstText(o?.latestCancellationStatus, o?.requests?.cancellation?.status); const refund = firstText(o?.latestCancellationRefundStatus, o?.requests?.cancellation?.refundStatus); if (status) rows.push(`<div class="ld-account-update-row"><span>Request status</span>${statusPill(cancellationStatusLabel(status), statusTone(status))}</div>`); if (refund) rows.push(`<div class="ld-account-update-row"><span>Refund status</span>${statusPill(refund, statusTone(refund))}</div>`); const explanation = firstText(o?.latestCancellationExplanation, o?.requests?.cancellation?.explanation); if (!rows.length && !explanation) return `<p class="ld-account-muted">No cancellation update.</p>`; return `<section class="ld-account-cancellation-update" aria-label="Cancellation update">${rows.join("")}${explanation ? `<div class="ld-account-update-explanation"><strong>Explanation</strong><p>${esc(explanation)}</p></div>` : ""}</section>`; }
