  function actionText(ok) { return ok ? "Available" : "Not currently available"; }
  function renderLineItems(o) { const items = asList(o.lineItems || o.items); if (!items.length) return ""; return `<h3>Items</h3><div class="ld-account-line-items">${items.map((item) => { const img = safeUrl(item.image || item.imageUrl); return `<div class="ld-account-line-item">${img ? `<img src="${esc(img)}" alt="">` : ""}<div><strong>${esc(item.title || item.name || "Item")}</strong>${item.variantTitle || item.variant ? `<span>${esc(item.variantTitle || item.variant)}</span>` : ""}${item.sku ? `<small>SKU: ${esc(item.sku)}</small>` : ""}<small>Qty: ${esc(item.quantity ?? 1)}</small></div><b>${moneyMajor(item.lineTotal || item.total || item.price || item.discountedTotal)}</b></div>`; }).join("")}</div>`; }
