  function renderDrawer(o) { closeDrawer(false); state.returnFocus = document.activeElement; const item = primaryItem(o); state.activeDrawerOrderKey = cancellationOrderNumber(o); const drawer = document.createElement("div"); drawer.className = "ld-account-drawer-wrap"; drawer.innerHTML = `<div class="ld-account-overlay" data-ld-close></div><aside class="ld-account-drawer" role="dialog" aria-modal="true" aria-label="Order details" tabindex="-1"><button class="ld-account-close" type="button" data-ld-close aria-label="Close order details">×</button><h2>${esc(item.title || o.name || o.orderName || "Order details")}</h2><p>${esc(cancellationOrderNumber(o) || "Order")} · ${date(o.processedAt || o.createdAt)} · ${itemCount(o) || 1} item(s) · ${moneyMajor(o.total || o.totalPrice || o.currentTotalPrice)}</p>${renderStatusRows(o, true)}${renderLineItems(o)}<h3>Shipment tracking</h3>${renderAllTracking(o)}<h3>Cancellation</h3>${renderCancellationAction(o)}<h3>Cancellation update</h3>${renderCancellationUpdate(o)}<h3>Request timeline</h3>${renderRequestTimelines(o)}<h3>Exchange</h3>${renderExchangeAction(o)}<h3>Exchange progress</h3>${renderProgress(o.exchangeProgress || o.requests?.exchange)}<h3>Issue reporting</h3>${renderIssueAction(o)}<h3>Issue update</h3>${renderIssueUpdate(o)}<h3>Request windows</h3>${renderDeadlines(o) || `<p class="ld-account-muted">No request deadline available.</p>`}<p>${uniqueReasons(o).map(esc).join(" · ") || "No active lock reason."}</p><div class="ld-account-actions"><span>Exchange: ${esc(actionText(o.canRequestExchange))}</span><span>Issue: ${esc(actionText(o.canReportIssue))}</span></div></aside>`; (root() || document.body).appendChild(drawer); document.body.classList.add("ld-account-scroll-lock"); drawer.querySelector(".ld-account-drawer").focus(); bind(); }
