  function reviewsApiUrl() { return "/apps/loopd2c/api/reviews/customer?page=" + encodeURIComponent(state.reviewPage) + "&pageSize=10"; }
  function reviewStatus(value) { const labels = { PENDING_MODERATION: ["Pending moderation", "Your review has been submitted and is awaiting approval.", "progress"], PUBLISHED: ["Published", "Your review is visible to shoppers.", "ok"], REJECTED: ["Not published", "This review was not published.", "bad"], HIDDEN: ["Not published", "This review is not currently visible to shoppers.", "neutral"], DRAFT: ["Pending moderation", "Your review is being processed.", "progress"], DELETED: ["Not published", "This review is not published.", "neutral"] }; return labels[value] || ["Pending moderation", "Your review is being processed.", "progress"]; }
  function reviewImage(item) { return item.productImageUrl ? `<img class="ld-review-image" src="${esc(item.productImageUrl)}" alt="${esc(item.productTitle)}">` : `<span class="ld-review-image ld-review-image-fallback" aria-hidden="true">No image</span>`; }
  function renderReviewCard(review) { const status = reviewStatus(review.status); return `<article class="ld-review-card">${reviewImage(review)}<div class="ld-review-content"><div class="ld-review-heading"><div><strong>${esc(review.productTitle || "Purchased product")}</strong>${review.variantTitle ? `<small>${esc(review.variantTitle)}</small>` : ""}${review.orderName ? `<small>Order ${esc(review.orderName)}</small>` : ""}</div><span class="ld-account-pill ld-account-pill-${esc(status[2])}">${esc(status[0])}</span></div><span class="ld-review-stars" aria-label="${esc(review.rating)} out of 5 stars">${"★".repeat(Number(review.rating) || 0)}${"☆".repeat(5 - (Number(review.rating) || 0))}</span>${review.title ? `<h3>${esc(review.title)}</h3>` : ""}${review.body ? `<p class="ld-review-body">${esc(review.body)}</p>` : ""}<div class="ld-review-meta">${review.verifiedPurchase ? "<span>✓ Verified purchase</span>" : ""}<time>Submitted ${esc(date(review.submittedAt))}</time></div><p class="ld-account-muted">${esc(status[1])}</p></div></article>`; }
  function renderAwaitingCard(item) { return `<article class="ld-review-card ld-review-awaiting">${reviewImage(item)}<div class="ld-review-content"><strong>${esc(item.productTitle || "Purchased product")}</strong>${item.variantTitle ? `<small>${esc(item.variantTitle)}</small>` : ""}${item.orderName ? `<small>Order ${esc(item.orderName)}</small>` : ""}${item.deliveredAt ? `<small>Delivered ${esc(date(item.deliveredAt))}</small>` : ""}<button type="button" class="ld-account-button ld-account-button-primary" data-ld-write-review="${esc(item.orderLineId)}">Write a review</button></div></article>`; }
  function renderReviews() { if (state.reviewsLoading) return `<section class="ld-account-card ld-reviews"><h2>My Reviews</h2><p>Loading your reviews…</p></section>`; if (state.reviewsError) return `<section class="ld-account-card ld-reviews"><h2>My Reviews</h2><p role="alert">${esc(state.reviewsError)}</p><button type="button" class="ld-account-button" data-ld-reviews-retry>Try again</button></section>`; const data = state.reviewsData; if (!data) return `<section class="ld-account-card ld-reviews"><div class="ld-review-heading"><h2>My Reviews</h2><button type="button" class="ld-account-button" data-ld-reviews-open>View My Reviews</button></div></section>`; const reviews = data.reviews || [], awaiting = data.awaitingReviews || [], pagination = data.pagination || {}; return `<section class="ld-account-card ld-reviews"><div class="ld-review-heading"><h2>My Reviews</h2><button type="button" class="ld-account-button" data-ld-reviews-close>Back to account</button></div><h3>Your reviews</h3>${reviews.length ? `<div class="ld-review-list">${reviews.map(renderReviewCard).join("")}</div>` : `<p class="ld-account-empty">You have not submitted any reviews yet.</p>`}${pagination.totalPages > 1 ? `<nav class="ld-review-pages" aria-label="Reviews pages"><button class="ld-account-button" data-ld-review-page="${pagination.page - 1}" ${pagination.hasPreviousPage ? "" : "disabled"}>Previous</button><span>Page ${esc(pagination.page)} of ${esc(pagination.totalPages)}</span><button class="ld-account-button" data-ld-review-page="${pagination.page + 1}" ${pagination.hasNextPage ? "" : "disabled"}>Next</button></nav>` : ""}<h3>Awaiting your review</h3>${data.reviewsEnabled === false ? `<p class="ld-account-muted">Reviews are currently unavailable. Your submitted reviews remain visible.</p>` : awaiting.length ? `<div class="ld-review-list">${awaiting.map(renderAwaitingCard).join("")}</div>` : `<p class="ld-account-empty">You have no delivered purchases awaiting review.</p>`}</section>`; }
